import{_ as a,o,c as t,a4 as r}from"./chunks/framework.BisFRKAV.js";const f=JSON.parse('{"title":"关于徐鸿铎","description":"大模型部署与平台开发实践，以及对模型原理、推理系统和训练方法的持续学习。","frontmatter":{"layout":"page","title":"关于徐鸿铎","description":"大模型部署与平台开发实践，以及对模型原理、推理系统和训练方法的持续学习。","kind":"about","status":"published","contentLang":"zh","translations":{"en":"/en/about"},"sidebar":false,"aside":false,"outline":false},"headers":[],"relativePath":"about.md","filePath":"about.md"}'),i={name:"about.md"};function l(n,e,s,p,h,c){return o(),t("div",null,[...e[0]||(e[0]=[r('<div class="profile-page"><header class="profile-header"><p class="profile-overline" lang="en">About</p><h1 id="profile" tabindex="-1">徐鸿铎 <a class="header-anchor" href="#profile" aria-label="Permalink to &quot;徐鸿铎 {#profile}&quot;">​</a></h1><p class="profile-bio">我在工作中参与大模型部署与模型管理平台开发。部署时遇到的延迟、资源与稳定性问题，让我开始追踪模型如何生成、训练如何改变输出，以及怎样用实验定位变化的来源。</p><nav class="profile-links" aria-label="作者链接"><a href="/articles/">已发布文章 <span aria-hidden="true">→</span></a><a href="https://github.com/xhongduo-tech" target="_blank" rel="noopener noreferrer">GitHub <span aria-hidden="true">↗</span></a></nav></header><section class="profile-section" aria-labelledby="profile-interests"><h2 id="profile-interests" tabindex="-1">关注方向 <a class="header-anchor" href="#profile-interests" aria-label="Permalink to &quot;关注方向 {#profile-interests}&quot;">​</a></h2><ul class="profile-focus"><li><h3>推理算法与服务系统</h3><p>从一次生成的状态出发，追踪解码、KV 缓存与请求调度。</p></li><li><h3>训练与后训练</h3><p>关注训练样本的标签位置、参数更新路径和独立样本上的行为变化。</p></li><li><h3>模型与系统评测</h3><p>比较变更前后的逐例差异，追查收益、退化与评测条件。</p></li></ul></section><section class="profile-section" aria-labelledby="profile-notebook"><h2 id="profile-notebook" tabindex="-1">关于这里 <a class="header-anchor" href="#profile-notebook" aria-label="Permalink to &quot;关于这里 {#profile-notebook}&quot;">​</a></h2><p>这个博客用于回答具体的大模型问题。例如，同一个 token 为什么能在两条推理路径上算出相同结果，或微调后 loss 下降时怎样检查任务能力。正式文章会保留机制推导、必要的源码入口、可复算例子和结论边界。</p><p>学习地图与全年任务保留在私有工作区。项目只有在形成真实记录后才进入文章；实测会注明模型版本、输入、配置与环境，不把论文结果写成个人实测。</p><nav class="profile-links" aria-label="博客链接"><a href="/articles/#topology-heading">查看领域拓扑 <span aria-hidden="true">→</span></a><a href="https://github.com/xhongduo-tech/xhongduo-tech.github.io" target="_blank" rel="noopener noreferrer">本站源码 <span aria-hidden="true">↗</span></a></nav></section></div>',1)])])}const u=a(i,[["render",l]]);export{f as __pageData,u as default};
